package com.feifei.phonebridge;
import android.app.*;
import android.content.*;
import org.json.*;
import java.util.concurrent.*;

/** Task controls stay available in the notification shade while Xianyu is foreground. */
final class TaskMonitor implements AutoCloseable {
 static final String ACTION="com.feifei.phonebridge.TASK_CONTROL";
 private final Context context; private final NativeSellerClient client;
 private final ScheduledExecutorService io=Executors.newSingleThreadScheduledExecutor();
 private String lastUiState="";private volatile JSONObject current; private volatile boolean controlFailure; private volatile boolean closed;
 TaskMonitor(Context context){this.context=context;NotificationManager old=context.getSystemService(NotificationManager.class);if(old!=null)old.cancel(8766);client=new NativeSellerClient(context);io.scheduleWithFixedDelay(this::refresh,0,5,TimeUnit.SECONDS);}
 private void refresh(){if(closed||CloudState.deviceId(context).isEmpty())return;try{String device=CloudState.deviceId(context);JSONObject inventory=client.inventory();if(!device.equals(CloudState.deviceId(context))||CloudState.isRevoked(context))return;String uiState=device+":"+TaskUiUpdates.stateKey(inventory);if(!uiState.equals(lastUiState)){lastUiState=uiState;TaskUiUpdates.publish(device,inventory);}JSONArray jobs=inventory.getJSONArray("jobs");java.util.Set<String> recipes=new java.util.HashSet<>();JSONArray plans=inventory.optJSONArray("builtins");if(plans!=null)for(int n=0;n<plans.length();n++){JSONObject plan=plans.optJSONObject(n);if(plan!=null&&java.util.Arrays.asList("daily_preheat_v5","daily_maintenance_v5").contains(plan.optString("id")))recipes.add(plan.optString("recipe_id"));}JSONObject job=null;for(int i=0;i<jobs.length();i++){JSONObject candidate=jobs.getJSONObject(i);if(java.util.Arrays.asList("queued","running","waiting","unknown").contains(candidate.optString("status"))){job=candidate;break;}}current=job;NotificationManager manager=context.getSystemService(NotificationManager.class);if(manager==null)return;if(job==null){ControlService.refreshNotification(context);return;}String mode=job.optString("control_state","active");String state=mode.equals("paused")?"已暂停":mode.equals("pausing")?"正在暂停":mode.equals("stopping")?"正在结束":job.optString("status").equals("unknown")?"结果需核对":"执行中";String text=(controlFailure?"控制未确认，请回OIN核对 · ":"")+state;Intent open=new Intent(context,NativeTaskActivity.class).putExtra("pause_job",job.optString("id")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);Notification.Builder builder=new Notification.Builder(context,"phonebridge_control").setSmallIcon(android.R.drawable.ic_media_play).setContentTitle(job.optString("name","OIN任务")).setContentText(text).setStyle(new Notification.BigTextStyle().bigText(text+"\n返回 OIN 可暂停、继续或结束本次任务。")).setContentIntent(PendingIntent.getActivity(context,8766,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE)).setOnlyAlertOnce(true).setOngoing(true);
 if(!job.optString("status").equals("unknown")){if(mode.equals("active")||mode.equals("paused")&&!job.optBoolean("requires_manual")&&recipes.contains(job.optString("recipe_id")))builder.addAction(new Notification.Action.Builder(null,mode.equals("paused")?(job.optBoolean("requires_manual")?"已手动完成并继续":"继续任务"):"暂停任务",action(job.optString("id"),mode.equals("paused")?"resume":"pause",8767)).build());if(!mode.equals("stopping"))builder.addAction(new Notification.Action.Builder(null,"结束任务",action(job.optString("id"),"stop",8768)).build());}manager.notify(8765,builder.build());}catch(Exception failure){JSONObject job=current;if(job!=null){NotificationManager manager=context.getSystemService(NotificationManager.class);if(manager!=null)manager.notify(8765,new Notification.Builder(context,"phonebridge_control").setSmallIcon(android.R.drawable.ic_media_pause).setContentTitle("任务连接暂不可用").setContentText("状态未同步，请回OIN核对；未确认暂停或结束").setOngoing(true).build());}}}
 private PendingIntent action(String id,String action,int code){if(action.equals("resume")){Intent open=new Intent(context,TaskResumeActivity.class).putExtra("job_id",id);return PendingIntent.getActivity(context,code,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}Intent intent=new Intent(context,ControlService.class).setAction(ACTION).putExtra("job_id",id).putExtra("task_action",action);return PendingIntent.getService(context,code,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 void control(Intent intent){String id=intent.getStringExtra("job_id"),action=intent.getStringExtra("task_action");if(id==null||!java.util.Arrays.asList("pause","resume","stop").contains(action))return;io.execute(()->{try{client.control(id,action);controlFailure=false;}catch(Exception ignored){controlFailure=true;}refresh();});}
 public void close(){closed=true;client.close();io.shutdownNow();}
}
